ash":"6c0e132d7a655a524a52225f6aa5ccb02b98c3fb66d91ef1689d86e06d6d4558","revision_hash":null,"published_at":"2026-10-29T10:50:00.000Z","body_expected":false},{"source":"Walter Football","url_hash":"60ee12fd834d1b2c641e59f581245a9dc851ddfaad7909f4e5e4e2436d3cebf7","revision_hash":null,"published_at":"2026-10-28T10:42:00.000Z","body_expected":false},{"source":"Walter Football","url_hash":"72682b7f51adf972de029e596ec8f5e1c4341e9952b9efb9dd35e7893b102cbf","revision_hash":null,"published_at":"2026-10-27T10:48:00.000Z","body_expected":false},{"source":"Walter Football","url_hash":"dbc6522298f37589254bdd964ab262f4a4c792fe1d45558f98de17e49f06905c","revision_hash":null,"published_at":"2026-10-27T10:48:00.000Z","body_expected":false},{"source":"Walter Football","url_hash":"2440c823e269f714949ad11d9c769cfc73463f138d5b12227ae2ad15aa65d1b0","revision_hash":null,"published_at":"2026-10-27T10:48:00.000Z","body_expected":false},{"source":"Action Network","url_hash":"5f3d4cdd36022e1e1445b49d01e98ae55bc09d6b993e406f68a51bdef345ca37","revision_hash":"bd9de595716aaba85357c48c2f28446e58fc971666b109829dcaa161d6074084","published_at":"2026-10-28T15:59:01.000Z","body_expected":true},{"source":"Action Network","url_hash":"04de4035d478c5328b19cc6bf04b14a1979402743b88f9d925658730cb9772e9","revision_hash":"113ba0234b1f7650999d1f9f85a68c01981f52777643dad1f51a713394e299bf","published_at":"2026-10-27T21:02:04.000Z","body_expected":true},{"source":"Action Network","url_hash":"1dc98d70a74f316cd0efe5f894596b809593da1ad31dc617dd381b1e8b62a48e","revision_hash":"288bd621732ca4686563ebcc6f4b2062555d07f7258b37268a1bca1be2da899f","published_at":"2026-10-27T21:01:19.000Z","body_expected":true},{"source":"Action Network","url_hash":"c7b741ba6f212cf7e16b7e5f277a56e1c8ed52b9775ce830a30699b13bcb3d8b","revision_hash":"e010b028953203ff761e3506ad2612c870d1a6b21195b9ce7a541f6af25d4a85","published_at":"2026-10-27T19:13:21.000Z","body_expected":true}]'::jsonb)
 AS x(source text,url_hash text,revision_hash text,published_at timestamptz,body_expected boolean)
), matched AS (
 SELECT x.*,b.id AS base_id,b.published_at AS stored_published_at,b.captured_at AS stored_captured_at,
 length(b.body) AS stored_body_chars,r.id AS revision_id,r.published_at AS revision_published_at,
 coalesce(btrim(b.body)<>'',false) AS base_body_nonempty
 FROM incoming x LEFT JOIN public.research_intel_notes b ON b.url_hash=x.url_hash
 LEFT JOIN public.research_intel_notes r ON r.url_hash=x.revision_hash
)
SELECT jsonb_build_object(
 'staged_candidates',(SELECT count(*) FROM matched),
 'base_notes_present',(SELECT count(*) FROM matched WHERE base_id IS NOT NULL),
 'missing_base_notes',(SELECT count(*) FROM matched WHERE base_id IS NULL),
 'staged_body_values',(SELECT count(*) FROM matched WHERE body_expected),
 'staged_body_candidates_with_nonempty_existing_body',(SELECT count(*) FROM matched WHERE body_expected AND base_body_nonempty),
 'staged_body_candidates_still_empty',(SELECT count(*) FROM matched WHERE body_expected AND NOT base_body_nonempty),
 'eligible_actionnetwork_revisions_missing',(SELECT count(*) FROM matched WHERE source='Action Network' AND base_id IS NOT NULL
   AND revision_hash IS NOT NULL AND published_at>=stored_published_at+interval '20 hours' AND revision_id IS NULL),
 'sources',(SELECT jsonb_agg(to_jsonb(s)) FROM (
   SELECT source,count(*) AS staged,count(base_id) AS base_present,count(*) FILTER(WHERE base_body_nonempty) AS with_existing_body
   FROM matched GROUP BY source ORDER BY source) s),
 'records',(SELECT jsonb_agg(to_jsonb(m)) FROM matched m)
) AS verification_receipt;
